#pragma once
#include "kstationMidiEventTask.h"
#include "kstationControllerExpressionApplyTask.h"
#include <optional>
namespace kstation {
class ControllerMidiExpressionTask final {
 using T=MidiExpressionEventTask;using S=T::Stage;using H=MidiEventHelperTask;using HS=H::Stage;
public:
 using Kind=T::Kind;using Child=T::Child;ControllerMidiExpressionTask(Kind kind,uint32_t payload):task_(kind),payload_(payload){}bool complete()const{return task_.complete();}bool awaitingChild()const{return task_.awaitingChild()&&!helper_&&(!apply_||apply_->awaitingChild());}Child child()const{return task_.child();}MidiApplyExpressionTask::Child applyChild()const{return apply_?apply_->child():MidiApplyExpressionTask::Child::LookupPart;}uint32_t partAddress()const{return apply_?apply_->partAddress():0;}uint8_t value()const{return task_.value();}bool resumeApply(MidiApplyExpressionTask::Child c){return apply_&&apply_->resume(c);}
 bool stackWrites()const{if(apply_)return apply_->stackWrites();if(helper_){auto s=helper_->stage();return s==HS::SaveInput||s==HS::SaveWord;}auto s=task_.stage();return s==S::StoreChannel||s==S::CheckChannel||s==S::Apply;}
 unsigned nextClocks(int previous=-1)const{if(apply_)return apply_->nextClocks(previous);if(helper_){switch(helper_->stage()){case HS::Complete:return 0;case HS::ReadChannel:case HS::ReadIndex:return 12;case HS::ReadProgramChannel:return 15;case HS::BindProgram:return 9;case HS::SaveInput:case HS::RestoreInput:case HS::SaveWord:case HS::RestoreWord:return 6;case HS::WriteChannel:return 6;case HS::Return:return 7;default:return 3;}}switch(task_.stage()){case S::Complete:case S::AwaitChild:return 0;case S::ReadFirst:return 6;case S::ReadSecond:return 9;case S::BindStorage:return 9;case S::StoreChannel:case S::CheckChannel:case S::Apply:return 10;case S::Return:return 7;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(apply_){auto used=apply_->advanceBefore(cost,read,write,previous);if(apply_->complete()){apply_.reset();task_.resume(task_.child());}return used;}if(helper_){auto kind=helper_->kind();bool ok=helper_->advance([&](H::Read f){return read(f==H::Read::ProgramChannel?0xbb16:0xcad5,1,cost);},[&](H::Write,uint32_t v){write(helper_->address(),v,1,cost);});if(!ok)return 0;if(helper_->complete()){auto match=helper_->matches();helper_.reset();task_.resume(kind==H::Kind::ChannelMatch?Child::ChannelMatch:Child::StoreChannel,match);}return cost;}bool ok=task_.advance([&](T::Read f){return read(payload_+(f==T::Read::Second?1:0),1,cost);});if(!ok)return 0;if(task_.awaitingChild()){if(task_.child()==Child::StoreChannel)helper_.emplace(H::Kind::StoreChannel,task_.storageBase(),task_.value());else if(task_.child()==Child::ChannelMatch)helper_.emplace(H::Kind::ChannelMatch);else if(task_.child()==Child::ApplyPitch||task_.child()==Child::ApplyPressure)apply_.emplace(task_.child()==Child::ApplyPitch?MidiApplyExpressionTask::Kind::Pitch:MidiApplyExpressionTask::Kind::Pressure,task_.value());}return cost;}
private:T task_;uint32_t payload_;std::optional<H>helper_{};std::optional<ControllerExpressionApplyTask>apply_{};
};
}
